const html='<!DOCTYPE html><html lang="en" class="dark"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Synara Notion UI Fixture</title></head><body><div id="root"></div><script type="module" src="/src/notionCapture.tsx"></script></body></html>';

const tsx = "import React from \"react\";\nimport { createRoot } from \"react-dom/client\";\nimport { QueryClient, QueryClientProvider } from \"@tanstack/react-query\";\nimport { NotionTaskDetails } from \"./components/notion/NotionTaskDetails\";\nimport { NotionMappingForm } from \"./components/notion/NotionMappingForm\";\nimport \"./index.css\";\nconst ids={\n  workspace:\"11111111-1111-4111-8111-111111111111\",\n  bot:\"22222222-2222-4222-8222-222222222222\",\n  source:\"33333333-3333-4333-8333-333333333333\",\n  page:\"44444444-4444-4444-8444-444444444444\",\n  sprintSource:\"55555555-5555-4555-8555-555555555555\",\n  sprint:\"66666666-6666-4666-8666-666666666666\"\n};\nconst connectionId=ids.workspace+\":\"+ids.bot;\nconst options={status:[{id:\"todo\",name:\"To do\"},{id:\"progress\",name:\"In progress\"},{id:\"done\",name:\"Done\"}],\n priority:[{id:\"low\",name:\"Low\"},{id:\"high\",name:\"High\"},{id:\"urgent\",name:\"Urgent\"}]};\nconst source={id:ids.source,object:\"data_source\",title:[{plain_text:\"Engineering sprint\"}],properties:{\n Name:{id:\"title\",type:\"title\",title:{}},\n Status:{id:\"status\",type:\"status\",status:{options:options.status}},\n Priority:{id:\"priority\",type:\"select\",select:{options:options.priority}},\n Sprint:{id:\"sprint\",type:\"relation\",relation:{data_source_id:ids.sprintSource}},\n Estimate:{id:\"points\",type:\"number\",number:{format:\"number\"}},\n Due:{id:\"due\",type:\"date\",date:{}}\n}};\nconst page={id:ids.page,object:\"page\",parent:{type:\"data_source_id\",data_source_id:ids.source},url:\"https://www.notion.so/\"+ids.page.replaceAll(\"-\",\"\"),properties:{\n Name:{id:\"title\",type:\"title\",title:[{type:\"text\",text:{content:\"Release sprint hardening\"},plain_text:\"Release sprint hardening\"}]},\n Status:{id:\"status\",type:\"status\",status:{id:\"progress\",name:\"In progress\"}},\n Priority:{id:\"priority\",type:\"select\",select:{id:\"high\",name:\"High\"}},\n Sprint:{id:\"sprint\",type:\"relation\",relation:[{id:ids.sprint}]},\n Estimate:{id:\"points\",type:\"number\",number:8},\n Due:{id:\"due\",type:\"date\",date:{start:\"2026-10-23\"}}\n}};\nconst mapping={id:\"fixture-mapping\",name:\"Engineering work\",connectionId,dataSourceId:ids.source,projectId:null,fields:{\n title:{id:\"title\",type:\"title\"},status:{id:\"status\",type:\"status\"},\n priority:{id:\"priority\",type:\"select\"},sprint:{id:\"sprint\",type:\"relation\"},\n points:{id:\"points\",type:\"number\"},due:{id:\"due\",type:\"date\"}\n},sprintPlan:null,completedStatusIds:[\"done\"],reopenedStatusId:\"todo\",priorityOptions:{low:\"low\",high:\"high\",urgent:\"urgent\"},agentAccess:\"none\",enabled:true};\nconst external={provider:\"notion\",connectionId,mappingId:mapping.id,dataSourceId:ids.source,pageId:ids.page,url:page.url,\n workspaceName:\"Engineering Workspace\",status:\"In progress\",statusId:\"progress\",assignees:[\"Morgan\"],assigneeIds:[],\n sprintIds:[ids.sprint],epicIds:[],milestoneIds:[],dependencyIds:[],subtaskIds:[],startDate:null,\n storyPoints:8,syncState:\"synced\",syncMessage:null,writableFields:[\"title\",\"notes\",\"priority\",\"dueDate\",\"completed\"]};\nconst todo={id:\"notion:\"+connectionId+\":\"+ids.page,title:\"Release sprint hardening\",\n notes:\"Validate task property synchronization before release.\",priority:\"high\",projectId:null,dueDate:\"2026-10-23\",\n threadId:null,delegationBaseTurnId:null,linkedAt:null,completedAt:null,\n createdAt:\"2026-10-14T00:00:00Z\",updatedAt:\"2026-10-15T00:00:00Z\",external};\n(window as any).nativeApi={notion:{\n state:async()=>({configured:true,connections:[{id:connectionId,workspaceId:ids.workspace,workspaceName:\"Engineering Workspace\",status:\"connected\",createdAt:\"2026-10-14T00:00:00Z\"}],mappings:[mapping],changes:[],syncing:false,lastSyncedAt:\"2026-10-15T00:00:00Z\",syncError:null}),\n read:async(input:any)=>({data:input.kind===\"dataSource\"?source:input.kind===\"page\"?page:input.kind===\"query\"?{results:[{id:ids.sprint,object:\"page\",parent:{data_source_id:ids.sprintSource},properties:{Name:{id:\"title\",type:\"title\",title:[{plain_text:\"Sprint 42\"}]}}}],has_more:false}:{results:[],has_more:false}}),\n write:async()=>({change:{state:\"synced\"},data:page}),sync:async()=>({}),saveMapping:async()=>({ok:true}),\n complete:async()=>({pending:true,connection:null}),connect:async()=>({}),disconnect:async()=>({ok:true}),deleteMapping:async()=>({ok:true}),resolve:async()=>({ok:true})\n},shell:{openExternal:async()=>{}}};\nconst screen=new URLSearchParams(location.search).get(\"screen\")||\"task\";\nfunction App(){return <main className=\"min-h-screen bg-background p-12 text-foreground\">\n <div className=\"mx-auto max-w-[980px] space-y-6\">\n  <div className=\"flex items-center justify-between gap-3\">\n   <p className=\"text-ui-lg font-semibold\">Synara <span className=\"font-normal text-muted-foreground\">/ {screen===\"mapping\"?\"Integration settings\":\"Tasks\"}</span></p>\n   <span className=\"rounded-full border border-border px-3 py-1 text-ui-xs text-muted-foreground\">Fixture data · no live Notion connection</span>\n  </div>\n  {screen===\"mapping\"?<section className=\"rounded-2xl border border-border bg-card p-6\">\n   <h1 className=\"mb-4 text-xl font-semibold\">Notion task mapping</h1>\n   <NotionMappingForm connectionId={connectionId} source={source} existing={mapping} onSaved={()=>{}} onCancel={()=>{}}/>\n  </section>:<section className=\"rounded-2xl border border-border bg-card p-7 shadow-lg\">\n   <div className=\"space-y-3 border-b border-border pb-6\">\n    <h1 className=\"text-xl font-semibold\">Release sprint hardening</h1>\n    <p className=\"text-ui-sm text-muted-foreground\">Engineering · Priority High · Due 23 Oct 2026</p>\n    <p className=\"text-ui text-muted-foreground\">Validate task property synchronization before release.</p>\n   </div>\n   <div className=\"pt-5\"><NotionTaskDetails todo={todo as any}/></div>\n  </section>}\n </div>\n</main>}\ncreateRoot(document.getElementById(\"root\")!).render(<QueryClientProvider client={new QueryClient()}><App/></QueryClientProvider>);\n";
const capture = "import { chromium } from \"playwright\";\nconst url=\"http://127.0.0.1:7390/notion-capture.html\";\nconst version=process.argv[2];\nconst output=process.argv[3];\nconst browser=await chromium.launch({headless:true,args:[\"--no-sandbox\"]});\nconst page=await browser.newPage({viewport:{width:1440,height:1050},deviceScaleFactor:1});\nconst errors=[];\npage.on(\"pageerror\",err=>errors.push(String(err)));\nawait page.goto(url,{waitUntil:\"domcontentloaded\",timeout:30000});\nawait page.getByText(\"Engineering Workspace\").first().waitFor({timeout:15000});\nawait page.screenshot({path:output+\"/\"+version+\"-task.png\",fullPage:true});\nif(version===\"after\"){\n await page.getByRole(\"button\",{name:\"Edit task properties\"}).click();\n await page.getByText(\"Task properties\",{exact:true}).waitFor({timeout:15000});\n await page.screenshot({path:output+\"/after-task-properties.png\",fullPage:true});\n}\nawait page.setViewportSize({width:1440,height:1950});\nawait page.goto(url+\"?screen=mapping\",{waitUntil:\"domcontentloaded\",timeout:30000});\nawait page.getByText(\"Map to Synara Tasks\").waitFor({timeout:15000});\nawait page.screenshot({path:output+\"/\"+version+\"-mapping.png\",fullPage:true});\nif(errors.length)throw Error(\"Browser page errors: \"+errors.slice(0,3).join(\" | \"));\nconsole.log(\"Captured \"+version+\" Task and mapping UI.\");\nawait browser.close();\n";
async function pause(ms){return new Promise(resolve=>setTimeout(resolve,ms));}
async function snapshot(ref,label){
 execFileSync("git",["checkout","--detach",ref],{cwd:root,stdio:"inherit"});
 await writeFile(path.join(web,"notion-capture.html"),html);
 await writeFile(path.join(web,"src","notionCapture.tsx"),tsx);
 await writeFile(path.join(web,"notion-capture.mjs"),capture);
 const vite=spawn(process.execPath,[path.join(web,"node_modules/vite/bin/vite.js"),"--host","127.0.0.1","--port","7390","--strictPort"],{cwd:web,env:{...process.env,PORT:"7390"},stdio:["ignore","pipe","pipe"]});
 let log="";
 vite.stdout.on("data",x=>log+=x.toString());
 vite.stderr.on("data",x=>log+=x.toString());
 try{
  let live=false;
  for(let i=0;i<80;i++){
   if(vite.exitCode!==null)throw Error("Vite quit: "+log.slice(-4000));
   try{const res=await fetch("http://127.0.0.1:7390/notion-capture.html");if(res.ok){live=true;break;}}catch{}
   await pause(500);
  }
  if(!live)throw Error("Vite startup timeout: "+log.slice(-4000));
  try{execFileSync(process.execPath,["notion-capture.mjs",label,out],{cwd:web,stdio:"inherit",timeout:120000});}
  catch(error){console.error("Vite log:",log.slice(-5000));throw error;}
 }finally{vite.kill("SIGTERM");await pause(2000);}
}
await snapshot(before,"before");
await snapshot(after,"after");
console.log("Captured real browser renders with fixed in-memory fixture data.");
